import React, { useState } from 'react';
import { Card, Input, DatePicker, Button, Space, Row, Col } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import HybridPathInput from './HybridPathInput';
import SourcesExcludedInput from './SourcesExcludedInput';
import { sources, getSourceCodenames } from './data/sources';
import './styles/NormalRouteBuilder.css';

const { RangePicker } = DatePicker;

const NormalRouteBuilder = ({ onSearch }) => {
  const [path, setPath] = useState('');
  const [sourcesExcluded, setSourcesExcluded] = useState([]);
  const [apiKey, setApiKey] = useState('');
  const [dateRange, setDateRange] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleSearch = async () => {
    if (!path || !apiKey || !dateRange) {
      // TODO: Add error handling for missing required fields
      return;
    }

    setIsLoading(true);

    try {
      // Get all available source codenames
      const allSources = getSourceCodenames();

      // Filter out excluded sources
      const includedSources = allSources.filter(source => !sourcesExcluded.includes(source));

      // Format dates
      const startDate = dateRange[0].format('YYYY-MM-DD');
      const endDate = dateRange[1].format('YYYY-MM-DD');

      const response = await fetch('http://backend-284998006367.us-central1.run.app/api/availability-v2', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Partner-Authorization': apiKey
        },
        body: JSON.stringify({
          routeId: path,
          startDate,
          endDate,
          sources: includedSources.join(',')
        })
      });

      if (!response.ok) {
        throw new Error('Search failed');
      }

      const data = await response.json();
      onSearch?.(data);
    } catch (error) {
      console.error('Search failed:', error);
      // TODO: Add error handling UI
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Card className="normal-route-builder">
      <Row gutter={[16, 16]} className="form-row">
        {/* Path Input */}
        <Col flex="6">
          <div className="form-item">
            <div className="element-label">Path:</div>
            <HybridPathInput
              value={path}
              onChange={setPath}
              placeholder="Enter path (e.g. NRT/HND-OAK/SFO-JFK/EWR)"
            />
          </div>
        </Col>

        {/* Sources Excluded */}
        <Col flex="1">
          <div className="form-item">
            <div className="element-label">Sources Excluded:</div>
            <SourcesExcludedInput
              value={sourcesExcluded}
              onChange={setSourcesExcluded}
            />
          </div>
        </Col>

        {/* API Key */}
        <Col flex="2">
          <div className="form-item">
            <div className="element-label">API Key:</div>
            <Input.Password
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              placeholder="Enter your API key"
            />
          </div>
        </Col>

        {/* Date Range */}
        <Col flex="2">
          <div className="form-item">
            <div className="element-label">Date Range:</div>
            <RangePicker
              value={dateRange}
              onChange={setDateRange}
              format="YYYY-MM-DD"
            />
          </div>
        </Col>

        {/* Search Button */}
        <Col flex="0 1 120px" className="search-button-col">
          <Button
            type="primary"
            onClick={handleSearch}
            disabled={!path || !apiKey || !dateRange}
            loading={isLoading}
            className="search-button"
            icon={<SearchOutlined />}
          >
            Search
          </Button>
        </Col>
      </Row>
    </Card>
  );
};

export default NormalRouteBuilder;
